{
  "concepts": [
    {
      "conditions": [],
      "definition": "F15 is the release and successor-conservation family. Its instance premises are recursive products, published cuts, mutable carriers, derived assets, external services and successor lines. It traces, but does not own, FOUNDATIONS §2 lineage objects. Its table distinguishes commitment-derived consequences from domain and policy choices and their owners.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 114,
          "quote": "Its instance premises, which the commitments do not supply, are",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 100
        }
      ],
      "key": "release_conservation_family",
      "label": "Release and successor conservation"
    },
    {
      "conditions": [],
      "definition": "The lineage taxonomy distinguishes substrate, development product, source project, release cut, product, install, artifact and product definition. A mutable source workspace lacks fixed product identity. An install used as builder substrate binds as a development product without transferring meaning or authority to the authored product. Product definition is a source-project surface rather than the released artifact.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 118,
          "quote": "substrate, development product, source project, release cut, product, install, artifact and product definition are distinct objects.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 118
        }
      ],
      "key": "lineage_objects",
      "label": "Product lineage objects"
    },
    {
      "conditions": [],
      "definition": "A stable repository-local key assigned by the Product release authority to one independently released source project.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 164,
          "quote": "- Project Release Namespace: a stable repository-local key assigned by\n  the Product release authority to one independently released source\n  project;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 162
        }
      ],
      "key": "project_release_namespace",
      "label": "Project Release Namespace"
    },
    {
      "conditions": [],
      "definition": "The exact repository-relative source-project root and Git tree object selected for one cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 166,
          "quote": "- Project Subtree: the exact repository-relative source-project root and\n  Git tree object selected for one cut;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 165
        }
      ],
      "key": "project_subtree",
      "label": "Project Subtree"
    },
    {
      "conditions": [],
      "definition": "The mutable source-project state constructing a possible successor; a realisation of FOUNDATIONS §2 Candidate Source.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 168,
          "quote": "- Candidate Source: the candidate source of FOUNDATIONS §2, the mutable\n  source-project state constructing a possible successor;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 167
        }
      ],
      "key": "candidate_source",
      "label": "Candidate Source"
    },
    {
      "conditions": [],
      "definition": "A mutable project-qualified carrier for the current candidate window.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 170,
          "quote": "- RC Branch: a mutable project-qualified carrier for the current\n  candidate window;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 169
        }
      ],
      "key": "rc_branch",
      "label": "RC Branch"
    },
    {
      "conditions": [],
      "definition": "An annotated project-qualified Git tag together with its exact Product release subject, identifying one published candidate and, once accepted, one released Product. It realises the release cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 173,
          "quote": "- Immutable RC Cut: an annotated project-qualified Git tag plus its exact\n  Product release subject (FOUNDATIONS §2), naming one published candidate\n  and, once accepted, one released Product; it realises the release cut;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 171
        }
      ],
      "key": "immutable_rc_cut",
      "label": "Immutable RC Cut"
    },
    {
      "conditions": [],
      "definition": "A mutable project-qualified tag alias naming the highest-ordinal published immutable RC cut for one project and version line. It is discovery rather than an exact operative basis or consumer authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 176,
          "quote": "- Version-Line Selector: the mutable project-qualified tag alias naming\n  the highest-ordinal published immutable RC cut for that project and\n  version line; it realises the version-line selector of FOUNDATIONS §2;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 174
        }
      ],
      "key": "version_line_selector",
      "label": "Version-Line Selector"
    },
    {
      "conditions": ["The optional carrier is used."],
      "definition": "An optional mutable project-qualified convenience carrier aligned to the selector's latest-published commit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 179,
          "quote": "- Release Branch: an optional mutable project-qualified convenience\n  carrier aligned to the same latest-published commit as the selector.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 178
        }
      ],
      "key": "release_branch",
      "label": "Release Branch"
    },
    {
      "conditions": [],
      "definition": "The release process has three ordered phases: mutable candidate construction; immutable RC publication with monotonic version-line advancement; exact-cut qualification, acceptance and explicit consumer adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 279,
          "quote": "1. mutable candidate construction;\n2. immutable RC publication and monotonic version-line advancement; and\n3. exact-cut qualification, acceptance and explicit consumer adoption.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F3.%20Phases",
          "start_line": 277
        }
      ],
      "key": "release_process",
      "label": "Release process"
    },
    {
      "conditions": [],
      "definition": "Qualification is evidence-based evaluation of the exact cut and its claims. Acceptance is the human Product authority's verdict over that immutable subject, distinct from publication, selector advancement and consumer adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 359,
          "quote": "An RC is accepted only when the required exact-cut review and operator\nchecks are complete and the human authority accepts that exact subject.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F3.%20Phases%2FExact-cut%20qualification",
          "start_line": 354
        }
      ],
      "key": "exact_cut_qualification",
      "label": "Exact-cut qualification and acceptance"
    },
    {
      "conditions": [],
      "definition": "Consumer adoption is a separate explicit Product-Definition transition that resolves, presents, installs, verifies and pins an immutable RC. Its read-only Adoption Plan binds current definition bytes and basis to the target cut, tag object, peeled commit, tree and installed-manifest digest, and emits a deterministic digest.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 435,
          "quote": "Presentation and mutation are separate invocations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F4.%20Selector%20and%20consumer%20adoption",
          "start_line": 425
        }
      ],
      "key": "consumer_adoption",
      "label": "Consumer adoption and Adoption Plan"
    },
    {
      "conditions": ["A surface is carried by the cut."],
      "definition": "Optional release-scoped surfaces include release notes, release and installed-distribution manifests, dependency declarations, package or installed-carrier metadata, qualification receipts, and branch and tag identity declarations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 477,
          "quote": "An immutable RC cut may carry release-scoped surfaces such as",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FRelease-scoped%20assets",
          "start_line": 469
        }
      ],
      "key": "release_scoped_assets",
      "label": "Release-scoped assets"
    },
    {
      "conditions": [],
      "definition": "The Product release subject is the declared exact Product member set or artifact. Release-scoped claim surfaces describe it; co-located mutable source-project fields can be explicitly excluded from both. The repository commit is their wider carrier, not automatic Product membership.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 504,
          "quote": "A repository commit carries those declared sets but does not make every\nco-located file or sibling Project Subtree a Product member.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FProduct%20subject%20and%20repository%20carrier",
          "start_line": 501
        }
      ],
      "key": "product_release_subject",
      "label": "Product release subject"
    },
    {
      "conditions": ["A Product authority explicitly declares the relation because a source corpus and required distributed or derived assets need to remain usable as one versioned set."],
      "definition": "A Release-Matched Asset Cohort is an explicitly declared cross-Product set naming every required Product and asset, exact source dependency, owning authorities, qualification boundary and publication transaction. The STDO stack's closed cohort consists of its exact standards cut; distributed spec plugin and host assets; exact Axiom Indexer mechanics Product; exact STDO Representation Product; and released a_c.STDO program and constraint map or equivalent semantic index, with complete source inventory, member digests, member-set digest and derivation cut identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 539,
          "quote": "For a release-matched STDO stack, the closed cohort contains all of",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts",
          "start_line": 528
        }
      ],
      "key": "release_matched_cohort",
      "label": "Release-Matched Asset Cohort"
    },
    {
      "conditions": ["A coordinated STDO cohort is being constructed."],
      "definition": "The bounded two-commit construction freezes source STDO in commit A and derived Products and cohort record in commit B. The installed manifest includes the annotated STDO tag object; placing that identity and its derived child bytes in the same commit would be self-referential. Local construction and qualification precede one atomic publication transaction.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 556,
          "quote": "Exact installed-manifest identity includes the annotated STDO tag object,\nso a same-commit carrier containing both that identity and derived child\nbytes would be self-referential.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts%2FTwo-commit%20construction%20and%20one%20publication%20transaction",
          "start_line": 552
        }
      ],
      "key": "cohort_publication",
      "label": "Two-commit cohort publication"
    },
    {
      "conditions": [],
      "definition": "A successor disposition is a claim about one affecting predecessor claim: conserved means retained; superseded means replaced by an accepted successor relation; intentionally removed means removed by current Product authority; not applicable means no successor effect with a bounded reason. These are predicates to evaluate, not result values. An unresolved disposition states no claim and has no result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 678,
          "quote": "- conserved: the successor retains the claim;\n- superseded: an accepted successor relation replaces it;\n- intentionally removed: current Product authority removes it; or\n- not applicable: it has no successor effect, with a bounded reason.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 675
        },
        {
          "end_line": 720,
          "quote": "An unresolved disposition states no claim and so has no result:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 714
        }
      ],
      "key": "successor_disposition",
      "label": "Successor semantic disposition"
    },
    {
      "conditions": [],
      "definition": "The source-disposition table records the member's claims that rc.2 RELEASE_METHOD rows are conserved and routed to current loci. Routes are provenance only. Recorded generalisations remove emphasis, replace method-relative references with §9 or this member, use British spelling, and render 'must remain usable' as the declaration condition 'need to remain usable', without a new obligation. Generic release objects are defined in FOUNDATIONS and realised here.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 755,
          "quote": "Every conserved row is restated in this member's own\ntext; a route is provenance only.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F11.%20Source%20dispositions",
          "start_line": 745
        }
      ],
      "key": "release_source_dispositions",
      "label": "Release source-disposition record"
    },
    {
      "conditions": [],
      "definition": "SPEC_METHOD is a Tier 2 particular-method member owning method identity and position, constitutional chain and surfaces, manifesto and litmus tests, requirement and design law, trace closure, live-surface law, outcome conservation, change management, consistency and sprint boundaries, ambiguity governance, lifecycle sufficiency, lineage, release-version boundary, migration, procedures, design records and build-tenant binding. It is realised from FOUNDATIONS, REFERENCE_FRAME, ACTIVATION and EVALUATION, not foundational itself. PRODUCT_DEFINITION, ASSURANCE, TICKETS and RELEASE respectively carry project binding, testing law, work carriers and release mechanics.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 24,
          "quote": "nothing here is foundational, every clause\nnames the principle that requires it",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD",
          "start_line": 14
        }
      ],
      "key": "spec_method",
      "label": "SPEC_METHOD"
    },
    {
      "conditions": [],
      "definition": "Spec-driven development treats specification as constitutional source to make software re-derivable, auditable and correctable under explicit authority. Its declarative bias recommends primarily declaring truths, structures, interfaces, constraints and evidence surfaces; imperative procedure remains subordinate to declared authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 38,
          "quote": "Its\noverriding bias is declarative rather than imperative:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FPosition",
          "start_line": 32
        }
      ],
      "key": "spec_driven_development",
      "label": "Spec-driven development"
    },
    {
      "conditions": [],
      "definition": "The method is a process constitution and meta-constitutional account of relationships, sufficiency, requirement truth and authority flow. It should bootstrap a new spec-driven process if implementation disappears; together with surviving domain specification it can reconstruct the project. Bound WHAT surfaces retain constitutional authority; design and realisation define HOW. Conventional paths locate roles without constituting mandatory layouts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 57,
          "quote": "Its role is meta-constitutional:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FProcess%20constitution",
          "start_line": 51
        }
      ],
      "key": "process_constitution",
      "label": "Process constitution"
    },
    {
      "conditions": ["Within urn:stdo:bounded-context:method-identity under the selected complete basis."],
      "definition": "STDO names four areas: Specification owned by SPEC_METHOD; Ticketing by TICKETS; Design by DESIGN_MODULE; Outcome-Driven Development, including its complete identity and realisation meaning, by ODD. An area is a body of method law, not an independently selectable released member.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 103,
          "quote": "The expansion does not make the four owning\nmembers independently selectable and does not reduce the released product\nto four members:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FMethod%20identity",
          "start_line": 100
        }
      ],
      "key": "stdo_method_identity",
      "label": "STDO method identity"
    },
    {
      "conditions": [],
      "definition": "F10 explains how specification governs realisations, under instance premises of owned layers, layered surfaces, several realisations and immutable releases. It distinguishes consequences from owned choices. Cited standing is P0 recovered; P1, P2, P3, P4a and P6 independent; P4b derived from P0 and P2 under non-reacquirability of step-produced facts; P5 derived from P0 and P6 under the open-world premise.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 163,
          "quote": "decides how a product's specification governs its realisations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FFoundation%20to%20law%3A%20chain%2C%20outcome%20and%20build-tenant%20binding",
          "start_line": 153
        }
      ],
      "key": "chain_binding_family",
      "label": "Chain, outcome and build-tenant binding family"
    },
    {
      "conditions": [],
      "definition": "The homeostatic chain is Goals → Intent → Product Definition → Requirements → Design → Code → Events → Projection → Delta → Scenarios → Gap analysis → Repricing at the change-class-selected layer. Every link is an owned responsibility. Code, Events and Projection use the selected execution binding's carriers; the chain does not demand a software codebase or event store where the binding selects neither.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 218,
          "quote": "Goals → Intent → Product Definition → Requirements → Design → Code\n  → Events → Projection → Delta → Scenarios → Gap analysis\n  → Repricing at the layer its change class names",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 216
        }
      ],
      "key": "constitutional_chain",
      "label": "Constitutional chain"
    },
    {
      "conditions": [],
      "definition": "Goals state current overriding concerns for a bounded work wave, more immediate than intent and higher-level than product definition and requirements. They keep temporary focus out of deeper layers until intentionally repriced there.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 259,
          "quote": "The goals surface is the bounded work-wave surface:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 255
        }
      ],
      "key": "goals_surface",
      "label": "Goals"
    },
    {
      "conditions": [],
      "definition": "Intent states purpose, direction, why the system exists and which directional changes are in or out of scope. It carries no optional realisation detail unless that detail is itself constitutional.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 419,
          "quote": "Intent states why the\nsystem exists and what directional change is in or out of scope; it carries\nno optional realisation detail unless that detail is itself constitutional.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FSpecification%20surface%20rule",
          "start_line": 417
        }
      ],
      "key": "intent_surface",
      "label": "Intent"
    },
    {
      "conditions": [],
      "definition": "The product-definition surface states the mutable source project's current concrete product, key terms, boundaries and decomposable end-state shape in present-tense terms. It bridges direction to requirements and is neither immutable release cut nor installed product. Its routing role binds actual authority locations and tenant realisations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 265,
          "quote": "It is not the immutable release cut\nand not the installed product;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 263
        }
      ],
      "key": "product_definition_surface",
      "label": "Product Definition"
    },
    {
      "conditions": [],
      "definition": "Requirements are the full constitutional WHAT: invariant truths, capabilities, constraints, governance and verification obligations that the project must make true. They have explicit acceptance criteria and must support downstream design derivation, including material lifecycle obligations or named ambiguity gaps.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 430,
          "quote": "Requirements state stable obligations\nthat must be true; they carry explicit acceptance criteria",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FSpecification%20surface%20rule",
          "start_line": 425
        }
      ],
      "key": "requirement_surface",
      "label": "Requirements"
    },
    {
      "conditions": [],
      "definition": "Design is the structural HOW: decisions, interfaces, carriers, topology, file placement, entry and control surfaces, runtime wiring, packaging and lawful tenant boundaries that realise requirement truth. ADRs are durable design records, not another constitutional layer above design or a second requirement surface.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 276,
          "quote": "Design is the structural how:",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 271
        }
      ],
      "key": "design_surface",
      "label": "Design and ADRs"
    },
    {
      "conditions": [],
      "definition": "Realisation performs design decisions as software, human procedure or both according to the selected execution environment. Events retain what happened in an event stream, ledger, signed record or observation log; Projection reconstructs current truth where that record suffices, without necessarily replaying a complete event stream. Delta reveals divergence from intended truth; Scenarios test operational meaning; Gap analysis exposes constitutional insufficiency; Repricing updates the lawful layer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 245,
          "quote": "Projection\nreconstructs current truth from that retained record where the record is\nsufficient for the product's obligations;",
